#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int longestBalanced(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        for (int l = 0; l < n; ++l) {
            unordered_set<int> seen;
            int balance = 0;
            for (int r = l; r < n; ++r) {
                if (seen.insert(nums[r]).second)
                    balance += (nums[r] % 2 == 0 ? 1 : -1);
                if (balance == 0) ans = max(ans, r - l + 1);
            }
        }
        return ans;
    }
};
